/**
 * 天气查询
 *
 * ## 数据源：Open-Meteo
 *
 * 选它的理由：
 *   - **不需要 API Key**，非商业免费
 *   - **多城市一次请求**：latitude/longitude 支持逗号分隔，3 个城市仍是 1 个请求
 *   - 数据来自官方气象机构（含中国 CMA）
 *
 * ## 两段式调用
 *
 *   1. 地理编码（城市名 -> 经纬度）：**只在设置里添加城市时调一次**，
 *      结果存进配置，之后不再调用。
 *   2. 取天气：每次查询天气发 **1 个请求**，可同时带回全部城市。
 *
 * 因此日常使用（已配置好城市）时，一次「天气」点击 = 1 个请求，约 1~2 KB。
 *
 * ## 缓存
 *
 * 同一批城市 1 小时内重复查询直接复用结果。天气本身不会分钟级变化，
 * 这样连点也不会产生多余请求。
 */

const GEO_URL = 'https://geocoding-api.open-meteo.com/v1/search';
const FORECAST_URL = 'https://api.open-meteo.com/v1/forecast';

/** 结果缓存时长：1 小时。 */
export const CACHE_TTL_MS = 60 * 60 * 1000;

/**
 * 天气查询的超时（毫秒）。
 *
 * 这个是**主功能**（点「天气」后要出结果），宁可多等一会也不要误判失败，
 * 因此给得宽松一些。
 */
const TIMEOUT_MS = 8000;

/**
 * 地理编码（搜城市）的单次超时。
 *
 * ## 为什么比天气查询短得多
 *
 * `geocoding-api.open-meteo.com` 解析出多个 IP，而**其中多数在部分
 * 网络下不可达**（实测 7 个里 5 个超时）。WebView 通常只试一个 IP，
 * 撞上坏的就只能等到超时。
 *
 * 而 `searchCity` 还要**依次尝试多种写法**（拼音 / 原样 / 补省份），
 * 若每次都等满 8 秒，最坏累计 24 秒 —— 用户看到的是「彻底没反应」，
 * 而不是「失败」。
 *
 * 改成 4 秒并配合重试：快速失败、多试几次，让 DNS 轮询有机会落到
 * 可用的 IP 上。实测可用 IP 的响应在 1.7~3.9 秒，4 秒足够。
 */
const GEO_TIMEOUT_MS = 4000;

/**
 * 地理编码的重试次数（含首次）。
 *
 * 坏 IP 占多数，单次命中可用的概率只有约 3/10。多试几次能显著提高
 * 成功率，而每次失败只要 4 秒，代价可接受。
 */
const GEO_RETRY = 3;

/** 重试之间的等待（毫秒），避免连续撞上同一个坏 IP。 */
const GEO_RETRY_DELAY_MS = 250;

/** 最多可配置的城市数。 */
export const MAX_CITIES = 3;

